import React, {
  cloneElement,
  useCallback,
  useEffect,
  useRef,
  useState,
} from 'react';

import { ChevronLeft, ChevronRight } from 'components/icon';
import { Divider } from 'components/UI/Divider';
import { omitTransientProps } from 'utils/emotion';

import {
  StyledTabsList,
  StyledTabsListDivider,
  TabsArrowButton,
  TabsListBox,
  TabsListContainer,
} from '../Tabs.styles';
import type { TabsListProps } from '../Tabs.types';

const SCROLL_STEP_PX = 30;

export const TabsList = React.forwardRef<
  React.ElementRef<typeof StyledTabsList>,
  TabsListProps
>(({ children, ...props }, forwardedRef) => {
  const elementRef = useRef<HTMLDivElement | null>(null);
  const lastChildRef = useRef<HTMLButtonElement | null>(null);
  const firstChildRef = useRef<HTMLButtonElement | null>(null);
  const rootRef = forwardedRef ?? elementRef;
  const [showLeftArrow, setShowLeftArrow] = useState(false);
  const [showRightArrow, setShowRightArrow] = useState(false);

  const scrollLeft = useCallback(() => {
    const element = elementRef.current;
    if (element) {
      element.scrollTo(element.scrollLeft + SCROLL_STEP_PX, 0);
    }
  }, []);

  const scrollRight = useCallback(() => {
    const element = elementRef.current;
    if (element) {
      element.scrollTo(element.scrollLeft - SCROLL_STEP_PX, 0);
    }
  }, []);

  useEffect(() => {
    const options: IntersectionObserverInit = {
      root: typeof rootRef === 'function' ? null : rootRef.current,
      rootMargin: '0px',
      threshold: 0.99,
    };
    const currentLastChildRef = lastChildRef.current;
    const currentFirstChildRef = firstChildRef.current;

    const lastChildObserver = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        setShowRightArrow(!entry.isIntersecting);
      });
    }, options);

    if (currentLastChildRef) {
      lastChildObserver.observe(currentLastChildRef);
    }

    const firstChildObserver = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        setShowLeftArrow(!entry.isIntersecting);
      });
    }, options);

    if (currentFirstChildRef) {
      firstChildObserver.observe(currentFirstChildRef);
    }

    return () => {
      if (currentLastChildRef) {
        lastChildObserver.unobserve(currentLastChildRef);
      }
      if (currentFirstChildRef) {
        firstChildObserver.unobserve(currentFirstChildRef);
      }
    };
  }, [rootRef]);

  const childCount = React.Children.count(children);

  return (
    <>
      <TabsListBox>
        {showLeftArrow ? (
          <TabsArrowButton aria-label="Scroll tabs left" type="button">
            <ChevronLeft onClick={scrollRight} size="medium" role="button" />
          </TabsArrowButton>
        ) : null}
        <TabsListContainer>
          <StyledTabsList {...omitTransientProps(props)} ref={rootRef}>
            {React.Children.map(children, (child, index) => {
              if (!React.isValidElement(child)) {
                return child;
              }

              return cloneElement(child, {
                ...child.props,
                ...(index === 0 && { ref: firstChildRef }),
                ...(index === childCount - 1 && { ref: lastChildRef }),
              });
            })}
          </StyledTabsList>
        </TabsListContainer>
        {showRightArrow ? (
          <TabsArrowButton aria-label="Scroll tabs right" type="button">
            <ChevronRight onClick={scrollLeft} size="medium" role="button" />
          </TabsArrowButton>
        ) : null}
      </TabsListBox>
      <StyledTabsListDivider>
        <Divider />
      </StyledTabsListDivider>
    </>
  );
});

TabsList.displayName = 'Tabs.List';
